package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int32 = 998244353

func add(x *int32, y int32) {
	*x += y
	if *x >= mod {
		*x -= mod
	}
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func b2i(b bool) int {
	if b {
		return 1
	}
	return 0
}

var reader *bufio.Reader

func readInt() int {
	n := 0
	c, err := reader.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = reader.ReadByte()
	}
	f := 1
	if c == '-' {
		f = -1
		c, err = reader.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, err = reader.ReadByte()
	}
	return n * f
}

var (
	n, m int
	dp   [31][21][21][21][21][2][2]int32
	x    [15]int
	y    [15]int
	px   [1 << 5]int
	py   [1 << 5]int
	nx   [1 << 5]int
	ny   [1 << 5]int
)

func main() {
	reader = bufio.NewReaderSize(os.Stdin, 1<<16)
	n = readInt()
	m = readInt()
	for i := 1; i <= n; i++ {
		x[i] = readInt()
		y[i] = readInt()
	}
	for i := 0; i <= (1<<uint(n))-1; i++ {
		for j := 1; j <= n; j++ {
			if (i>>uint(j-1))&1 == 1 {
				if x[j] > 0 {
					px[i] += abs(x[j])
				} else {
					nx[i] += abs(x[j])
				}
				if y[j] > 0 {
					py[i] += abs(y[j])
				} else {
					ny[i] += abs(y[j])
				}
			}
		}
	}
	dp[0][0][0][0][0][0][0] = 1
	for i := 0; i <= 29; i++ {
		for cpx := 0; cpx <= 19; cpx++ {
			for cnx := 0; cnx <= 19; cnx++ {
				for cpy := 0; cpy <= 19; cpy++ {
					for cny := 0; cny <= 19; cny++ {
						for bx := 0; bx <= 1; bx++ {
							for by := 0; by <= 1; by++ {
								if dp[i][cpx][cnx][cpy][cny][bx][by] != 0 {
									for msk := 0; msk <= (1<<uint(n))-1; msk++ {
										npx := cpx + px[msk]
										npy := cpy + py[msk]
										nnx := cnx + nx[msk]
										nny := cny + ny[msk]
										if (npx & 1) != (nnx & 1) {
											continue
										}
										if (npy & 1) != (nny & 1) {
											continue
										}
										cx := npx & 1
										cy := npy & 1
										mx := (m >> uint(i)) & 1
										my := mx
										var nbx, nby int
										if cx == mx {
											nbx = bx
										} else {
											nbx = b2i(cx > mx)
										}
										if cy == my {
											nby = by
										} else {
											nby = b2i(cy > my)
										}
										add(&dp[i+1][npx>>1][nnx>>1][npy>>1][nny>>1][nbx][nby], dp[i][cpx][cnx][cpy][cny][bx][by])
									}
								}
							}
						}
					}
				}
			}
		}
	}
	fmt.Print((dp[30][0][0][0][0][0][0] + mod - 1) % mod)
}
